WITH filtered AS (SELECT *, ADD_MONTHS(shipped_date, 6) AS shipped_date_plus_months, DATEDIFF(delivered_date, shipped_date) AS days_shipped_date_to_delivered_date, COALESCE(carrier, 'N/A') AS carrier_filled FROM shipments WHERE cost BETWEEN 34 AND 35) SELECT CASE WHEN days_shipped_date_to_delivered_date >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END AS days_shipped_date_to_delivered_date_tier, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, COUNT(CASE WHEN carrier = 'Flash' THEN 1 END) AS flash_count, STDDEV_SAMP(cost) AS cost_stddev, SIZE(COLLECT_SET(carrier)) AS num_carriers, COUNT(*) AS event_count FROM filtered GROUP BY 1 ORDER BY event_count NULLS LAST
